    private static TraceSegment Segment(string display, int round, double[,] rows)
    {
        var samples = new List<TimedPose>();
        for (var i = 0; i < rows.GetLength(0); i++)
        {
            samples.Add(new TimedPose(rows[i, 0], new HeadPose(rows[i, 1], rows[i, 2], rows[i, 3], rows[i, 4], rows[i, 5], rows[i, 6])));
        }

        return new TraceSegment(display, round, samples);
    }
